-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
CREATE OR REPLACE VIEW staging.stg_tpch_erp__partsupp AS
with changes as (

    select * from raw_tpch_erp.partsupp

),

-- A change feed: each key's latest change, and no key whose latest change deleted it.
source as (

    select *
    from (
        select
            changes.*,
            row_number() over (
                partition by ps_partkey, ps_suppkey
                order by _ingested_at desc
            ) as _change_rank
        from changes
    ) as ranked
    where _change_rank = 1

),

final as (

    select
        cast(source.ps_partkey as BIGINT) as ps_partkey,
        cast(source.ps_suppkey as BIGINT) as ps_suppkey,
        cast(source.ps_availqty as INTEGER) as ps_availqty,
        cast(source.ps_supplycost as DECIMAL(15,2)) as ps_supplycost,
        cast(source.ps_comment as VARCHAR) as ps_comment,
        source._ingested_at as _ingested_at,
        source._batch_id as _batch_id,
        'tpch_erp' as _source_system,
        MD5(COALESCE(CAST(source.ps_partkey AS TEXT), '') || '|' || COALESCE(CAST(source.ps_suppkey AS TEXT), '') || '|' || COALESCE(CAST(source.ps_availqty AS TEXT), '') || '|' || COALESCE(CAST(source.ps_supplycost AS TEXT), '') || '|' || COALESCE(CAST(source.ps_comment AS TEXT), '')) as _record_hash
    from source

)

select * from final;
